// 配音工作流的本地路径解析。
//
// 后端把角色库与缓存放在应用数据目录下 (`<appdata>/characters`, `<appdata>/tts`)。
// 前端需要拼出参考音频的绝对路径交给 GSOV, 因此这里复刻同一套路径规则。
// 路径规则若调整, 必须与 `editor/src-tauri/src/service/voice/mod.rs` 同步。

import { appDataDir } from '@tauri-apps/api/path';

let cachedRoot: string | null = null;

/** 应用数据目录 (带缓存) */
export async function appDataRoot(): Promise<string> {
  if (!cachedRoot) cachedRoot = await appDataDir();
  return cachedRoot;
}

/** 角色库根目录 */
export async function charactersRoot(): Promise<string> {
  return join(await appDataRoot(), 'characters');
}

/** 配音缓存根目录 */
export async function cacheRoot(): Promise<string> {
  return join(await appDataRoot(), 'tts');
}

/** 以当前平台的风格拼接路径 */
export function join(...parts: string[]): string {
  const separator = navigator.userAgent.includes('Windows') ? '\\' : '/';
  return parts
    .map((part, index) => (index === 0 ? part.replace(/[\\/]+$/, '') : part.replace(/^[\\/]+|[\\/]+$/g, '')))
    .filter((part) => part.length > 0)
    .join(separator);
}
